import json
N=28; separators={4,9,14,19,24}; bands=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
g=[[0]*N for _ in range(N)]
for r in separators:g[r]=[8]*N
for c in separators:
 for r in range(N):g[r][c]=8
# Draw the demonstrated panel-to-panel segments.
def set_panel(pr,pc,val):
 a,b=bands[pr]; c,d=bands[pc]
 for r in range(a,b):
  for j in range(c,d):
   if g[r][j] not in (8,):
    g[r][j]=6 if {g[r][j],val}=={2,3} else val
   else: raise ValueError('separator overlap')
# Color 3 joins markers in panel column 2, rows 0 through 4.
for pr in range(5):set_panel(pr,2,3)
# Color 2 joins row-1 markers across columns 0 through 4.
for pc in range(5):set_panel(1,pc,2)
# Color 2 joins row-1 and row-3 markers down column 0.
for pr in range(1,4):set_panel(pr,0,2)
assert len(g)==28 and all(len(row)==28 for row in g)
print(json.dumps(g,separators=(',',':')))

import json
N=28; bands=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]; div={4,9,14,19,24}
g=[[0]*N for _ in range(N)]
for r in div:g[r]=[8]*N
for c in div:
 for r in range(N):g[r][c]=8
# Colored paths in panel coordinates: 2: row 1, cols 0..4 and col 0, rows 1..3; 3: col 2, rows 0..4.
paths={2:{(1,c) for c in range(5)}|{(r,0) for r in range(1,4)},3:{(r,2) for r in range(5)}}
for (pr,pc) in set().union(*paths.values()):
 colors=[color for color, cells in paths.items() if (pr,pc) in cells]
 val=6 if len(colors)>1 else colors[0]
 a,b=bands[pr]; c,d=bands[pc]
 for r in range(a,b):
  for j in range(c,d):g[r][j]=val
assert len(g)==28 and all(len(row)==28 for row in g)
print(json.dumps(g,separators=(',',':')))
